// https://storybook.js.org/docs/7.0/preact/writing-stories/introduction
import { expect } from 'storybook/test';
import type { Meta, StoryObj } from '@storybook/preact-vite';
import ProgressSpinner, {
  ProgressSpinner as component,
  ProgressSpinnerProps,
} from '@adobe-commerce/elsie/components/ProgressSpinner';
import { Search } from '@adobe-commerce/elsie/icons';
import { ActionButton, Button, Card, Icon, RadioButton, ImageSwatch } from '..';

/**
 * Use Progress Spinners to display ongoing activity or loading status.
 */
const meta: Meta<ProgressSpinnerProps> = {
  title: 'Components/ProgressSpinner',
  component,
  argTypes: {
    size: {
      type: 'select',
      table: {
        defaultValue: {
          summary: 'small',
        },
      },
      options: ['small', 'medium', 'big', 'large'],
      description: 'Size of the spinner',
    },
    stroke: {
      type: 'select',
      table: {
        defaultValue: {
          summary: '4',
        },
      },
      options: ['1', '2', '3', '4'],
      description: 'Stroke of the spinner',
    },
    active: {
      type: 'boolean',
      table: {
        defaultValue: {
          summary: 'true',
        },
      },
      options: [true, false],
      description:
        'Whether the spinner is active or not (not a prop, just for story).',
    },
    ariaLabel: {
      type: {
        required: false,
        name: 'string',
      },
      table: {
        defaultValue: {
          summary: 'Updating',
        },
      },
      description: 'Aria label for the spinner',
    },
  },
};

export default meta;

type Story = StoryObj<ProgressSpinnerProps>;

/**
 * ```ts
 * import { ProgressSpinner } from '@adobe-commerce/elsie/components/ProgressSpinner';
 * ```
 */

export const SmallSpinner: Story = {
  args: {
    ariaLabel: 'Updating',
    size: 'small',
    stroke: '4',
  },
  render: ({ ariaLabel, size, stroke }) => (
    <ProgressSpinner aria-label={ariaLabel} size={size} stroke={stroke} />
  ),
  play: async () => {
    const loaderIcon = document.querySelector(
      'div[class*="dropin-progress-spinner"]'
    ) as HTMLElement;
    await expect(loaderIcon).toBeVisible();
  },
};

export const LargeSpinnerWithCard: Story = {
  args: {
    ariaLabel: 'Updating',
    size: 'large',
    stroke: '4',
    active: true,
  },
  render: ({ ariaLabel, size, stroke, active }) => {
    const components = (
      <Card variant={'secondary'}>
        <h2 style={{ font: 'var(--type-headline-2-strong-font)' }}>Title</h2>
        <p style={{ font: 'var(--type-body-2-default-font)' }}>
          This is a short description of the item and should be kept to two or
          three lines as maximum.
        </p>
        <ActionButton disabled={active} children={'Action'} />
      </Card>
    );

    return active ? (
      <ProgressSpinner
        aria-label={ariaLabel}
        size={size}
        stroke={stroke}
        style={{ backgroundColor: 'var(--color-neutral-200);' }}
      >
        {components}
      </ProgressSpinner>
    ) : (
      components
    );
  },
  play: async () => {
    const loaderIcon = document.querySelector(
      'div[class*="dropin-progress-spinner"]'
    ) as HTMLElement;
    await expect(loaderIcon).toBeVisible();
  },
};

export const MediumSpinnerWithRadio: Story = {
  args: {
    ariaLabel: 'Updating',
    size: 'medium',
    stroke: '4',
    active: true,
  },
  render: ({ ariaLabel, size, stroke, active }) => {
    const components = (
      <div>
        <p style={{ font: 'var(--type-body-2-default-font)' }}>
          This is a short description of the item and should be kept to two or
          three lines as maximum.
        </p>
        <RadioButton
          label={'Option 1'}
          value={'1'}
          name={'radio'}
          description={'first option'}
          disabled={active}
        />
        <RadioButton
          label={'Option 2'}
          value={'2'}
          name={'radio'}
          description={'second option'}
          disabled={active}
        />
      </div>
    );

    return (
      <Card variant={'secondary'}>
        <h2 style={{ font: 'var(--type-headline-2-strong-font)' }}>Title</h2>
        {active ? (
          <ProgressSpinner aria-label={ariaLabel} size={size} stroke={stroke}>
            {components}
          </ProgressSpinner>
        ) : (
          components
        )}
      </Card>
    );
  },
  play: async () => {
    const loaderIcon = document.querySelector(
      'div[class*="dropin-progress-spinner"]'
    ) as HTMLElement;
    await expect(loaderIcon).toBeVisible();
  },
};

export const SmallSpinnerReplaceButton: Story = {
  args: {
    ariaLabel: 'Updating',
    size: 'small',
    stroke: '2',
    active: true,
  },
  render: ({ ariaLabel, size, stroke, active }) => (
    <Card variant={'secondary'}>
      <h2 style={{ font: 'var(--type-headline-2-strong-font)' }}>Title</h2>
      <p style={{ font: 'var(--type-body-2-default-font)' }}>
        This is a short description of the item and should be kept to two or
        three lines as maximum.
      </p>
      <div>
        <Button
          size="medium"
          style={{
            width: '100%',
            background: 'var(--color-brand-500) 0 0% no-repeat padding-box',
          }}
          aria-hidden={active}
          aria-label={active ? 'loading' : 'Action'}
          disabled={active}
          children={
            active
              ? [
                  <ProgressSpinner
                    aria-label={ariaLabel}
                    tabIndex={-1}
                    size={size}
                    stroke={stroke}
                    key="spinner"
                  />,
                ]
              : [
                  'Action!',
                  <Icon
                    source={Search}
                    size="24"
                    className="storybook_icon"
                    stroke="1"
                    viewBox="0 0 24 24"
                    aria-label="Search"
                    key={'4'}
                  />,
                ]
          }
        />
      </div>
    </Card>
  ),
  play: async () => {
    const loaderIcon = document.querySelector(
      'div[class*="dropin-progress-spinner"]'
    ) as HTMLElement;
    await expect(loaderIcon).toBeVisible();
  },
};

